presets.customCss:
body::before {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141288ba.webp') no-repeat center center / cover !important;
  z-index: -999 !important;
  pointer-events: none;
}

.xs-panel {
  --xs-bg: transparent; 
  --xs-tile-bg: rgba(255, 255, 255, 0.95); 
  --xs-text: #000000;
  --xs-muted: #666666;
  --xs-accent: #000000;
  --xs-border: #000000;
  --xs-cap: #000000;
  --xs-action-bg: #FFFFFF;
  --xs-done-bg: #FFFFFF;

  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;

  width: 100% !important;
  max-width: 100% !important;
  margin: 0 auto !important; 
  padding: 20px 16px !important; 
  border-radius: 0px !important;
}

.xs-frame {
  width: 100% !important;
  max-width: 100% !important;
}

.xs-tile, 
.xs-tile-deep, 
.xs-tile-thought {
  background: #FFFFFF !important;
  border: 1px solid #000000 !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  opacity: 1 !important;
}

.xs-tile-deep .xs-tile-v,
.xs-tile-deep .xs-tile-k,
.xs-tile .xs-tile-v,
.xs-tile .xs-tile-k {
  color: #000000 !important;
}

.xs-action {
  background: #FFFFFF !important;
  border: 1px solid #000000 !important;
  color: #000000 !important;
}

.xs-history {
  background: #FFFFFF !important;
  border: 1px solid #000000 !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

.xs-history-item {
  background: transparent !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.2) !important;
}

.xs-done {
  background: #FFFFFF !important;
  color: #000000 !important;
  border: 1px solid #000000 !important;
  opacity: 1 !important;
}
